define({"topics":[{"title":"<span class=\"ph\">Shutting down<span class=\"ph\">\/powering off<\/span> the host computer<\/span>","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_Parent_6.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e58956","topics":[]},{"title":"Applying LOTO - Integrated System Cabinet (ISC)","shortdesc":"<p class=\"shortdesc\">Apply LOTO to the Power Distribution Unit (PDU) when servicing this item in the Integrated System Cabinet (ISC). Applying LOTO ensures a safe environment when working on this part.<\/p>","href":"t_LOTO-for-ISC-Integrated-System-Cabinet_14845718_5.html","attributes":{"data-id":"id_13106290"},"menu":{"hasChildren":false},"tocID":"id_13106290-d46e59062","topics":[]},{"title":"Removing the magnet service access trim","shortdesc":"<p class=\"shortdesc\">Removes the service access trim. The trim panel covers the screws securing the front and rear service access panels.<\/p>","href":"t_RemovingTheServiceAccessTrim_4.html","attributes":{"data-id":"id_2002821"},"menu":{"hasChildren":false},"tocID":"id_2002821-d46e59164","topics":[]},{"title":"Removing the magnet front service access panel","shortdesc":"<p class=\"shortdesc\">Removes the front service access panel from the magnet to allow access to components mounted on the left-hand side of the magnet.<\/p>","href":"t_RemovingTheFrontServiceAccessPanel_4.html","attributes":{"data-id":"id_2002823"},"menu":{"hasChildren":false},"tocID":"id_2002823-d46e59266","topics":[]},{"title":"Removing the magnet rear service access panel","shortdesc":"<p class=\"shortdesc\">Removes the rear service access panel from the magnet to allow access to components mounted on the left-hand side of the magnet.<\/p>","href":"t_RemovingTheRearServiceAccessPanel_4.html","attributes":{"data-id":"id_2002966"},"menu":{"hasChildren":false},"tocID":"id_2002966-d46e59368","topics":[]},{"title":"Replacing the PAC","shortdesc":"<p class=\"shortdesc\"\/>","href":"t_ReplacingThePAC.html","attributes":{"data-id":"id_2011560"},"menu":{"hasChildren":false},"tocID":"id_2011560-d46e59470","topics":[]},{"title":"Installing the magnet rear service access panel","shortdesc":"<p class=\"shortdesc\">Installs the rear service access panel onto the magnet enclosure. This panel covers the components mounted on the left-hand side of the magnet.<\/p>","href":"t_InstallingTheRearServiceAccessPanel_4.html","attributes":{"data-id":"id_2002967"},"menu":{"hasChildren":false},"tocID":"id_2002967-d46e59571","topics":[]},{"title":"Installing the magnet front service access panel","shortdesc":"<p class=\"shortdesc\">Installs the front service access panel onto the magnet enclosure. This panel covers the components mounted on the left-hand side of the magnet.<\/p>","href":"t_InstallingTheFrontServiceAccessPanel_4.html","attributes":{"data-id":"id_2002825"},"menu":{"hasChildren":false},"tocID":"id_2002825-d46e59673","topics":[]},{"title":"Installing the magnet service access trim","shortdesc":"<p class=\"shortdesc\">Installs the service access trim. The trim panel covers the screws securing the front and rear service access panels.<\/p>","href":"t_InstallingTheServiceAccessTrim_4.html","attributes":{"data-id":"id_2002822"},"menu":{"hasChildren":false},"tocID":"id_2002822-d46e59775","topics":[]},{"title":"Removing LOTO - Integrated System Cabinet (ISC)","shortdesc":"<p class=\"shortdesc\">Removing locks and tags, and restoring power to the ISC (Integrated System Cabinet) Power Distribution Unit (PDU).<\/p>","href":"t_Removing-LOTO-ISC-Pioneer_5.html","attributes":{"data-id":"id_2016646"},"menu":{"hasChildren":false},"tocID":"id_2016646-d46e59877","topics":[]},{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_7.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e59980","topics":[]},{"title":"Doing the Signal Processing Unit (SPU) to Physiological Acquisition Controller (PAC) loopback diagnostic","shortdesc":"<p class=\"shortdesc\">The Signal Processing Unit (SPU) to Physiological Acquisition Controller (PAC) loopback diagnostic verifies that the ICE board can send data to the PAC module over the PAC's fiber optic cables.<\/p>","href":"c_SPU-to-PAC-Loopback_14922552.html","attributes":{"data-id":"id_13106306"},"menu":{"hasChildren":true},"tocID":"id_13106306-d46e60085","next":"id_13106306-d46e60085"},{"title":"Doing the Signal Processing Unit (SPU) to Physiological Acquisition Controller (PAC) IF loopback test","shortdesc":"<p class=\"shortdesc\">The Signal Processing Unit (SPU) to Physiological Acquisition Controller (PAC) IF loopback test verifies that the PAC TX and RX port on the ICE board (J38, J39) is functioning correctly.<\/p>","href":"c_SPU-to-PAC-IF-Loopback_14945168_2.html","attributes":{"data-id":"id_13106308"},"menu":{"hasChildren":false},"tocID":"id_13106308-d46e60805","topics":[]},{"title":"Doing the Signal Protection Unit (SPU) to Field Programmable Gate Array (FPGA) loopback test","shortdesc":"<p class=\"shortdesc\">The Signal Protection Unit (SPU) to Field Programmable Gate Array (FPGA) loopback test verifies the data path in the PAC I\/F in the PSC FPGA on the Integrated Control Engine (ICE) board.<\/p>","href":"c_SPU-to-FPGA-Loopback_14947538_5.html","attributes":{"data-id":"id_13106309"},"menu":{"hasChildren":true},"tocID":"id_13106309-d46e61213","next":"id_13106309-d46e61213"},{"title":"Doing a Physiological Acquisition Controller (PAC) respiratory test","shortdesc":"<p class=\"shortdesc\">The Physiological Acquisition Controller (PAC) respiratory test causes the PAC module to test its respiratory gain and offset circuits.<\/p>","href":"c_PAC-Resp_14922440.html","attributes":{"data-id":"id_13106305"},"menu":{"hasChildren":false},"tocID":"id_13106305-d46e61419","topics":[]},{"title":"Doing the Signal Processing Unit (SPU) cardiac diagnostic","shortdesc":"<p class=\"shortdesc\">The Signal Processing Unit (SPU) cardiac diagnostic verifies that the trigger signals (cardiac trigger), which are launched from SPU in Integrated Control Engine (ICE), could be correctly captured by the sequencer module in ICE.<\/p>","href":"r_diag_SPU-Cardiac-Diagnostics_14947545.html","attributes":{"data-id":"id_13106310"},"menu":{"hasChildren":false},"tocID":"id_13106310-d46e61523","topics":[]},{"title":"Doing the Signal Processing Unit (SPU) respiratory diagnostic","shortdesc":"<p class=\"shortdesc\">This Signal Processing Unit (SPU) respiratory diagnostic verifies that the trigger signals (respiratory trigger), which are launched from the SPU in Integrated Control Engine (ICE), could be correctly captured by the sequencer module in ICE.<\/p>","href":"r_diag_SPU-Respiratory-Diagnostics_14947547.html","attributes":{"data-id":"id_13106311"},"menu":{"hasChildren":false},"tocID":"id_13106311-d46e61626","topics":[]}]});